\version "2.27.2"
% automatically converted by musicxml2ly from 46a-Barlines.xml
\pointAndClickOff

\header {
  texidoc = "Different types of (non-repeat) bar lines: default (no setting),
    regular, dotted, dashed, heavy, light-light, light-heavy, heavy-light,
    heavy-heavy, tick, short, none."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1 | % 1
  R1 \bar "|" % 2
  R1 \bar ";" % 3
  R1 \bar "!" % 4
  R1 \bar "." % 5
  R1 \bar "||" % 6
  R1 \bar "|." % 7
  R1 \bar ".|" % 8
  R1 \bar ".." % 9

  \barNumberCheck #10
  R1 \bar "'" % 10
  R1 \bar "," % 11
  R1 \bar "" % 12
  R1 | % 13
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
